// SPDX-License-Identifier: Apache-2.0
//! THE MODEL-GEOMETRY DOOR — the only part of the KTIR → SuperDSC lowering that stays on this side,
//! and the reason it stays is that it cannot cross.
//!
//! ⭐ THE LOWERING ITSELF IS [`ktir_superdsc::emit::lower_ktir_to_superdsc`]. What is left here is
//! the name-keyed dispatch ([`lower`]) plus the two arms that turn a model's head geometry into
//! CONST GENERICS: [`scratchy_subtile::model_geometry`]'s `with_config_attn_geometry` /
//! `with_config_head_dim`, whose match arms are GENERATED by that crate's `build.rs` from every
//! checked-in `crates/models/arch/*/configs/*.json`.
//!
//! ⛔ THAT ARM SET IS THE CONSUMER'S MODEL INVENTORY, SO A LEAF CRATE MUST NOT OWN IT. It cannot be
//! received as data either — the whole point is that the values become `const` parameters, i.e. a
//! MONOMORPHISATION site. So the crate exposes
//! [`attn_at`](ktir_superdsc::emit::lower_ktir_to_superdsc::attn_at)`::<NQH, NKVH, HD>` and
//! [`rope_at`](ktir_superdsc::emit::lower_ktir_to_superdsc::rope_at)`::<HD>` as public generic entry
//! points and THE CALLER CROSSES THE DOOR. A third-party KTIR producer instantiates them from its
//! own configs; every build-time refusal here (a geometry with no arm is a loud bake error citing
//! `geometry_sources()`) is unchanged.
//!
//! ⭐⭐ AND THAT IS ALSO WHY THE MODEL'S AND THE BUNDLE'S OWN FACTS LIVE HERE. [`BundleAttnParams`] is
//! `ibm/main`'s `lower_one_node` parameter set for the attention path — the head geometry and the
//! attention multiplier off `SubOp::AttnDecode`, the swept rung and the row kind off the walk — and it
//! is an ARGUMENT of [`lower`], not a record on the program. `AttnFacts` was that record, and it let
//! the emulator (which executes the ops) and the card (which read the record) compute different
//! attention; the leaf crate now reads the six operand identities and the resident capacity out of the
//! program itself (`attn_operands`) and takes these four from whoever crossed the door.
//!
//! ⛔ THE TWO NEWTYPES BELOW ARE THE ORPHAN RULE, NOT A DESIGN. `OnAttnGeometry`/`OnHeadDim` are
//! `scratchy-subtile`'s traits and `AttnAt`/`RopeAt` are `ktir-superdsc`'s structs — neither is
//! local, so the impls need a type of THIS crate's own to hang on. They carry no logic: each wraps
//! the crate's argument pack and hands it straight to the generic entry point.

use ktir_superdsc::emit::EmittedOp;
use ktir_superdsc::emit::lower_ktir_to_superdsc as lk;
use ktir_superdsc::emit::lower_ktir_to_superdsc::{
    Error, Region, attn_at, err, regions, rope_at, split_out,
};
use ktir_superdsc::emit::whole_function::lower_function;
use ktir_superdsc::ktir_node::{KtirNode, Program};
use ktir_superdsc::placement::BundleLayout;

/// ⭐⭐⭐ THE FOUR THINGS THE PROGRAM CANNOT STATE — `ibm/main`'s `lower_one_node` PARAMETERS, at the
/// site that now needs them.
///
/// main lowered each node during the tape walk, so it read these straight off what it had in hand:
/// the head geometry and the attention multiplier from `node.op`'s `SubOp::AttnDecode` payload (the
/// numbers the `#[forward]` macro parsed out of the model config), and `active_cap` /
/// `rows_are_requests` from its own walk parameters, threaded down from the ladder driver. This split
/// lowers per BUNDLE instead, one pass later, so the same four facts are stated for the bundle at the
/// same place they were read — and they are read ONCE, off the graph's own `AttnDecode` nodes, by
/// [`crate::lower_subtile_tape_to_ktir::attn_bundle_params`].
///
/// ⛔ THIS IS NOT A RECORD ON THE PROGRAM, AND THE DIFFERENCE IS THE WHOLE POINT. `AttnFacts` hung
/// eleven fields off [`KtirNode`], so information flowed `SubtileIR → AttnFacts → SuperDSC` past the
/// IR: a third-party producer could not fill it, and the emulator (which runs the ops) and the card
/// (which read the record) were not obliged to agree. Seven of those eleven are now read out of the
/// program by `attn_operands`; these four are ARGUMENTS of the call, one value per bundle, supplied by
/// the caller on THIS side of the geometry door — which is where model and bundle facts legitimately
/// live (see the module header). A Triton producer's caller states its own, from its own configs.
///
/// `None` for a bundle with no attention node: an attention program arriving without these is a build
/// error naming them, never a descriptor built on a default.
#[derive(Clone, Copy, Debug)]
pub struct BundleAttnParams {
    /// main's `lower_one_node(.., rows_are_requests, ..)`.
    ///
    /// ⛔ THE GEOMETRY IS NO LONGER HERE, AND THE REASON IS THE HYBRID MODEL. This used to carry the
    /// bundle's ONE `SubOp::AttnDecode { geom }` — a fact under the assumption that one `#[forward]`
    /// expansion has one attention geometry. Gemma-4 falsifies that assumption: its sliding layers run
    /// (nqh=16, nkvh=8, hd=256) and every sixth layer runs a GLOBAL class (nqh=16, nkvh=1, hd=512), so
    /// one graph carries TWO and no per-bundle value can describe both. The program's own views state
    /// the geometry of the attention they compute (`q`'s view is `[mq, nqh·hd]`, a kv stream's is
    /// `[·, nkvh·hd]`, and its first access tile on `q` is `hd` wide), so the door MINTS the geometry
    /// there — the same reading rope already does for its head dim, and the same direction the scale,
    /// `mq` and the swept extent all took: facts the program states are read from the program, and a
    /// fact only the caller knows stays a caller's argument. The row KIND is the one that stays: no
    /// program states it, for the reason its own comment gives.
    pub rows_are_requests: bool,
    /// ⭐ WHETHER THIS BUNDLE'S ATTENTION READS THE PAGED KV THROUGH AN INDEX — the batched rungs'
    /// per-page gather (`rows_are_requests`) or the one-request rung's split-KV chunk
    /// ([`Self::chunk_pages`]). Prefill does not gather: its rows are consecutive positions of one
    /// sequence sharing one resident history, so there is nothing per-row for an index to select.
    ///
    /// ⛔ IT IS `rows_are_requests || chunk_pages.is_some()` AND NOTHING WIDER. A one-request body that
    /// took the PER-PAGE gather would read its mask per row (the gathered score arm has no broadcast
    /// arm) while placing and staging the broadcast row — measured on card as garbage from the first
    /// decode token. So a one-request body gathers only as a chunk, whose read IS the broadcast row
    /// over the chunk's logical slots. The placement reserves `KV_BLOCK_INDEX_TID` under this fact and
    /// the emitter names the index under it — one predicate, both halves.
    pub gathers_kv: bool,
    /// ⭐⭐⭐⭐⭐ THE SPLIT-KV CHUNK — how many resident pages this one-request decode body attends in ONE
    /// pass (`ktir_superdsc::sdsc_abstract::ChunkScratch`). A ladder rung's own bake fact: the attention
    /// PROGRAM sweeps one page whatever the rung, so the chunk width cannot be read back from it, and it
    /// is folded into the bundle fingerprint for exactly that reason. `None` = the per-page fold.
    pub chunk_pages: Option<u32>,
    /// ⭐ WHETHER THIS BUNDLE'S ATTENTION SCORE SCALE IS CARRIED BY THE STAGED WEIGHTS — and it is
    /// here because both cases that make it so leave the program UNABLE to state the one fact that
    /// remains.
    ///
    /// The score multiplier was the one thing the program stated and the door read back
    /// (`program_score_scale`, on the `qk · scale` mulf). A FOLD rewrites the node's scale to 1.0
    /// before the splice mints the program, and the triton→ktir pipeline folds a multiply by 1.0
    /// away entirely — so a folded attention program states NO multiplier, which is the truth (no
    /// device multiply is left to do: the weights carry `√scale` each). A model whose attention
    /// scale genuinely IS 1.0 (gemma-4's arch defaults `attention_multiplier` to it) states none
    /// either, for the same reason and just as truthfully — `√1.0` leaves the weights carrying
    /// the whole scale with nothing folded. This bool is the caller's statement that one of those
    /// two is the case, and the door HARD-REFUSES a multiplier-less program without it — a fact
    /// about what the program cannot say, not a value duplicated from what it does (the
    /// caller-stated `f32` this struct once carried beside the program's own reading, and lost
    /// for exactly that reason).
    pub scale_in_weights: bool,
    /// ⭐ WHETHER THIS BUNDLE'S o_proj READS THE HEAD-MAJOR COPY — the finalize/weight contract of
    /// the multi-slab single-row body, and the SECOND fact the program cannot state.
    ///
    /// At `nslab > 1` the shipped finalize relayouts `out` to token-stream at `nqh·nslab` ops; at
    /// `mq == 1` a row IS a head, so the alternative is to leave `out` slab-major (one op per slab)
    /// and permute o_proj's contraction axis to meet it — a SECOND, k-shuffled copy of each layer's
    /// o_proj weight under [`crate::reserved_tids::oproj_headmajor_tid`]. The finalize cannot say
    /// which arrangement its bytes are in, and the o matmul cannot say which copy its B operand
    /// means — this ONE fact is what both consume, so the restructure cannot be half-applied:
    /// the door swaps the B operand on exactly the bundles whose finalize went slab-major.
    ///
    /// Minted ONLY where fully expressible: the attention output is a single row (`mq == 1`),
    /// the head dim spans more than one feature slab (`hd > POOL_STICK`), and the o matmul is fp8
    /// W8A8 (the staging walk the permuted copy is derived for). A wider bundle, a single-slab head
    /// dim, or a dense o_proj keeps the shipped emission byte-for-byte.
    pub headmajor_handoff: bool,
    /// The o matmul's weight tid — the MatmulTile found by DATAFLOW (its A operand is an attention
    /// output), stated per bundle so the matmul door's swap keys on the OPERAND's identity and
    /// never on a shape: at `k == n` (granite-3.1-8b's `[4096, 4096]` o_proj) the extents cannot
    /// tell the o matmul from any other square projection, and a shape-keyed swap would re-point
    /// every square projection at the permuted copy. `None` when the graph's attention has no
    /// matmul consumer (nothing to swap; the handoff above is `false` with it).
    pub oproj_wtid: Option<u32>,
}

// ══════════════════════════════════════════════════════════════════════════════════════════════
//  THE DISPATCH — by the node kind the producer wrote into the program's name.
// ══════════════════════════════════════════════════════════════════════════════════════════════

/// One KTIR program → the SuperDSC descriptors main's body for that node kind emits.
///
/// ⭐⭐⭐ THE GENERIC KINDS GO THROUGH THE ONE WALK. The pointwise kinds (elementwise, silumul,
/// rmsnorm, scalarmul), the matmuls (fp16 and fp8 W8A8) and the LmLast copy are lowered by
/// [`lower_function`] — the same per-op walk the whole-function door is — rather than by
/// per-`Program` arms of their own: one implementation of each body, reached from both doors, so
/// the two cannot drift about what a silu or a contraction emits. The walk classifies each op
/// from the program's own ops (chain recognizers, splat/bound tiebreaks, the 1:1 map), proves
/// what the per-`Program` arms assumed (the matmul's B orientation, from `indexing_maps`), and
/// folds a row-blocked pointwise family into one whole-view descriptor (see
/// `whole_function::row_tiled_family`).
///
/// ⛔ THE fp8 ACTIVATION-QUANTIZE DEDUP IS NOT THREADED THROUGH THE WALK, AND THAT IS STATED
/// RATHER THAN SILENT. The per-`Program` matmul arm took main's per-BUNDLE dedup set, so q/k/v
/// reading one rms output quantized it once; the walk states its set per op (see `emit_one`'s
/// Matmul arm), so each fp8 matmul node emits its own quantize chain — same numerics, more ops,
/// until the set is threaded across the walk's calls. This door no longer takes the set: a
/// parameter nothing reads is a lie about behavior, and the follow-up that threads the dedup
/// adds it where it is consumed.
///
/// `attn_params` is [`BundleAttnParams`] — main's own remaining parameters, for the two bodies whose
/// device laws need a fact no program states.
pub fn lower(
    k: &KtirNode,
    sym_id_base: &mut i64,
    layout: Option<&BundleLayout>,
    attn_params: Option<BundleAttnParams>,
) -> Result<Vec<EmittedOp>, Error> {
    // The name is still the program's identity for the emulator (which keys functions by it) and for
    // the descriptor suffixes, so it is READ — but nothing is parsed out of it.
    let name = k.func.name;
    let r = regions(k)?;
    // ⭐⭐⭐ ON THE TYPE, NOT ON THE NAME. This was `match name.split('_').next()`, so a program's kind
    // was a substring the producer wrote and this side parsed back out — a typo was a runtime refusal
    // and a new kind fell through a `_` arm. `KtirNode::program` states it, so there is NO catch-all
    // here and a producer that gains a kind is an E0004 at this match.
    match k.program {
        // ⛔ EVERY POINTWISE KIND is held to the column windows its program states, on what it EMITS
        // (`lk::column_windows_are_honoured`). The front end column-tiles only some of them
        // (`subtile_ir.rs`'s set); for the rest the guard is a no-op at
        // corner 0, and it makes a corner that ever reaches one a build error naming the op, not a
        // piece written at the buffer base.
        Program::Elementwise(_) => windowed(name, &r, lower_function(k, layout, sym_id_base, None)),
        Program::SiluMul => windowed(name, &r, lower_function(k, layout, sym_id_base, None)),
        Program::RmsNorm => windowed(name, &r, lower_function(k, layout, sym_id_base, None)),
        Program::ScalarMul => windowed(name, &r, lower_function(k, layout, sym_id_base, None)),
        // ⭐ THE TOKEN DRAW — the whole-function walk, like every pointwise kind:
        // a straight-line body of whole-row reduces, equality compares and staged-table
        // multiplies over generic ops, whole-tensor at corner 0 (the splice's own
        // region guard refuses a windowed one). No door fact is read off the program.
        Program::Sample => windowed(name, &r, lower_function(k, layout, sym_id_base, None)),
        // ⭐ THE KV WRITE'S HARDWARE SCATTER — the step's K and V rows written into their pools
        // through the write-rows table (`lk::paged_kv_write`, the vendor's `test_scatter_1core`).
        Program::PagedKvWrite => lk::paged_kv_write(name, k, &r, sym_id_base, layout),
        // ⛔ NOT PORTED: the paged attention's card lowering (its page gathers in the walk loop) does
        // not exist yet — see `Program::has_card_lowering`. Refused by name, so a card build stops
        // here.
        Program::PagedAttn => Err(Error {
            message: format!(
                "{name}: {:?} has no SuperDSC lowering — the paged attention runs as KTIR on the \
                 emulator; its card lowering (page gathers and the KV scatter) is not ported",
                k.program
            ),
        }),
        // ⭐ THE CHAINED HEAD'S ROW PRODUCTION — the same no-door-to-cross shape as the
        // transpose: the three legs (slab gather, restickify transpose, row gather) are
        // parameterised by the extents its own regions state. See [`lk::embed_row_gather`]
        // and [`ktir_superdsc::ktir_node::Program::EmbedRowGather`] for the laws (the
        // weight read in place, the one-entry index law, the sentinel living with the
        // producer).
        Program::EmbedRowGather { .. } => lk::embed_row_gather(name, k, &r, sym_id_base, layout),
        // ⭐ THE CHAINED HEAD'S PICK DECOMPOSE — three one-entry u32 table gathers the
        // same copy door assembles (`lk::chain_stage`): the pick's word 0 indexes the
        // two staged decompose tables, landing the persistent s/l sticks and the fresh
        // s-value stick.
        Program::ChainStage { .. } => lk::chain_stage(name, k, &r, sym_id_base, layout),
        Program::RmsNormUnit => {
            windowed(name, &r, lk::rmsnorm_unit(name, k, &r, sym_id_base, layout))
        }
        // The fused per-head norm sandwich — the door derives its geometry off the
        // program's own views (one head's window is the output's first access tile), so its corners
        // are per-head windows this guard does not describe.
        Program::WindowedRmsNorm { .. } => lk::windowed_rmsnorm(name, k, &r, sym_id_base, layout),
        Program::TanhSoftCap => {
            windowed(name, &r, lk::tanhsoftcap(name, k, &r, sym_id_base, layout))
        }
        Program::ScalarWeightMul => {
            windowed(name, &r, lk::scalarweightmul(name, &r, sym_id_base, layout))
        }
        Program::Reshape => lk::reshape(name, &r, sym_id_base, layout),
        // ⭐ THE WALK PROVES WHAT THIS ARM HARDCODED. The per-`Program` matmul entry assumed
        // `TransposeB` and `OperandOrigin::Staged`; the walk reads the orientation off the op's own
        // `indexing_maps` (`whole_function::matmul_b_orientation`) and states the operands' origin
        // as windows — the facts the spurious-pad drop in `matmul_oriented` discriminates on. The
        // head-major swap fact is threaded exactly as before.
        Program::Matmul => lower_function(
            k,
            layout,
            sym_id_base,
            // ⭐ THE HEAD-MAJOR SWAP'S DOOR FACT, from the same `BundleAttnParams` the rope/attn
            // arms read: the o matmul's weight tid, named per bundle by the dataflow walk. Every
            // other matmul of the bundle (q/k/v, mlp, lm_head) carries a tid the fact does not
            // name, so it keeps its own staged weight — the swap is keyed on the operand's
            // identity, never a shape. ⛔ A handoff without an `oproj_wtid` is a malformed bundle
            // statement — the handoff is minted only where the walk found the o matmul — and a
            // slab-major finalize with no weight to meet it is refused here, not emitted.
            match attn_params {
                Some(p) if p.headmajor_handoff => Some(lk::HeadmajorOproj {
                    oproj_wtid: p.oproj_wtid.ok_or_else(|| Error {
                        message: format!(
                            "{name}: the bundle states the head-major attention finalize but \
                             names no o_proj weight tid — the handoff is minted only where the \
                             dataflow walk found the o matmul, so a handoff without one is a \
                             malformed bundle statement",
                        ),
                    })?,
                }),
                _ => None,
            },
        ),
        // The last-row extraction is a PURE COPY (loads and stores only); the walk's own LmLast
        // arm keys on the stated `Program` and refuses a copy that grew a compute op rather than
        // half-lowering it.
        Program::LmLast => lower_function(k, layout, sym_id_base, None),
        Program::Rope => rope(name, &r, sym_id_base, layout, attn_params),
        Program::Attn => attn(name, k, &r, sym_id_base, layout, attn_params),
        // ⭐ NO DOOR TO CROSS. A transpose's descriptor is parameterised by the two extents its own
        // program states and by nothing about the model, so the arm is the body — unlike `rope`/`attn`
        // above, whose head geometry has to become const generics on this side.
        Program::Transpose => lk::transpose(name, &r, sym_id_base, layout),
    }
}

/// A column-tiled body's ops, held to the windows its program states
/// ([`lk::column_windows_are_honoured`]): the bake fails naming the op rather than baking a piece
/// that writes another piece's columns.
fn windowed(
    name: &str,
    r: &[Region],
    ops: Result<Vec<EmittedOp>, Error>,
) -> Result<Vec<EmittedOp>, Error> {
    let ops = ops?;
    lk::column_windows_are_honoured(name, r, &ops)?;
    Ok(ops)
}

/// The orphan-rule carrier for [`lk::AttnAt`] — see the module header.
struct AttnAt<'a>(lk::AttnAt<'a>);

impl scratchy_subtile::model_geometry::OnAttnGeometry for AttnAt<'_> {
    type Out = Result<Vec<EmittedOp>, Error>;
    fn on_geometry<const NQH: u32, const NKVH: u32, const HD: u32>(
        self,
        geom: scratchy_subtile::sdsc_abstract::AttnGeometry<NQH, NKVH, HD>,
    ) -> Self::Out {
        attn_at::<NQH, NKVH, HD>(self.0, geom)
    }
}

/// ⭐ THE DOOR. main's `lower_attn_node` read its cache identity off `node.inputs` and `ir.tensors`,
/// its geometry and multiplier off the node's `SubOp`, and `active_cap`/`rows_are_requests` off its
/// call site. The cache identity and multiplier the PROGRAM states, so `attn_at` reads them there
/// (`attn_operands`); the row kind is [`BundleAttnParams`], main's own walk parameter, stated for
/// this bundle by the caller. `mq` is `q`'s own view's row count, which is what main's `TileOp` `mb`
/// dim was.
///
/// ⭐⭐ THE GEOMETRY IS MINTED HERE, OFF THE PROGRAM'S OWN VIEWS. It used to ride the bundle as one
/// `SubOp::AttnDecode { geom }` per expansion — sound only while one model had one attention class.
/// Gemma-4's layers alternate a SLIDING class (nqh=16, nkvh=8, hd=256) with a GLOBAL one
/// (nqh=16, nkvh=1, hd=512), so one graph carries two and no per-bundle value describes both. The
/// program states its own: `q`'s view is `[mq, nqh·hd]`, a kv stream's is `[·, nkvh·hd]`, and the
/// first access tile over `q` is `hd` wide — the same three readings `attn_operands` already makes
/// under a caller-stated geometry, so minting from them is not a new derivation but the existing one
/// with its input source moved. The GQA divisibility proof is spent at the same `mint` it always
/// was; a program whose views do not divide is a build error naming them.
fn attn(
    name: &str,
    k: &KtirNode,
    r: &[Region],
    sym_id_base: &mut i64,
    layout: Option<&BundleLayout>,
    attn_params: Option<BundleAttnParams>,
) -> Result<Vec<EmittedOp>, Error> {
    let p = attn_params.ok_or_else(|| Error {
        message: format!(
            "{name}: an attention program reached the lowering with no `BundleAttnParams`. Its row \
             kind is this bundle's (main's own walk parameter — whether its rows are separate \
             requests or one prompt's positions) and no KTIR states it, so the caller must state it \
             at the door."
        ),
    })?;
    // ── THE PROGRAM'S OWN GEOMETRY ── `q` is parameter 0 (checked against the store order in
    // `attn_operands`); a kv stream is the first K view after `q`/`out`; the head dim is the first
    // access tile's width over `q` — the tile whose corner is `arith.constant` at decode and
    // `pid·hd` at prefill, so the TILE's own Shape is the one reading that holds at both.
    let q = r.first().ok_or_else(|| Error {
        message: format!(
            "{name}: an attention program states {} parameter(s); its construction mints at least \
             six (q, out, and each segment's K then V)",
            r.len()
        ),
    })?;
    let kv_cols = {
        // The runtime length mask is a SYNTHETIC parameter (`[1, cap]`) that `KtirFunc::attn` mints
        // between `out` and the segments — `attn_operands` filters it by `k.mask`, and so does this
        // reading, or the mask's capacity would be read as a kv stream's width.
        let mask_tid = k.mask.map(|b| b.get());
        r.iter().skip(2).find_map(|x| {
            (x.tid != q.tid && Some(x.tid) != mask_tid && !x.is_out).then_some(x.v_cols)
        })
    };
    let (Some(q_cols), Some(kv_cols), Some((_, hd))) = (
        Some(q.v_cols),
        kv_cols,
        lk::param_first_tile(&k.func, &k.func.arguments[0].0),
    ) else {
        return Err(Error {
            message: format!(
                "{name}: the program does not state a complete geometry — `q`'s view is \
                 `[{}, ·]`, a kv stream is {} wide, and `q`'s first access tile is {} — one of the \
                 three is absent, so the head counts this door needs cannot be read off it",
                q.v_rows,
                kv_cols
                    .map(|c| c.to_string())
                    .unwrap_or_else(|| "missing".into()),
                lk::param_first_tile(&k.func, &k.func.arguments[0].0)
                    .map(|(_, c)| c.to_string())
                    .unwrap_or_else(|| "absent".into()),
            ),
        });
    };
    if hd == 0 || q_cols % hd != 0 || kv_cols % hd != 0 {
        return Err(Error {
            message: format!(
                "{name}: the program's own views do not divide into a geometry — `q` is {q_cols} \
                 wide, a kv stream {kv_cols}, the head-dim window {hd}; a head must tile both \
                 widths exactly or no GQA grouping exists"
            ),
        });
    }
    let geom = scratchy_subtile::model_geometry::ModelAttnGeometry::mint(
        scratchy_subtile::model_geometry::QueryHeads::new(q_cols / hd),
        scratchy_subtile::model_geometry::KvHeads::new(kv_cols / hd),
        scratchy_subtile::model_geometry::HeadDim::new(hd),
    )
    .ok_or_else(|| Error {
        message: format!(
            "{name}: the geometry read off the program's views (nqh={}, nkvh={}, head_dim={hd}) has \
             no GQA grouping — the kv-head count does not divide the query-head count, so \
             `AttnGeometry` cannot be named at it",
            q_cols / hd,
            kv_cols / hd,
        ),
    })?;
    // ⭐⭐ THE ONE PLACE THE MODEL'S HEAD GEOMETRY STOPS BEING VALUES for the attention path — the SAME
    // door `lower_one_node` crossed, now crossed with the geometry the program itself states.
    scratchy_subtile::model_geometry::with_config_attn_geometry(
        geom,
        AttnAt(lk::AttnAt {
            name,
            k,
            r,
            rows_are_requests: p.rows_are_requests,
            gathers_kv: p.gathers_kv,
            chunk_pages: p.chunk_pages,
            scale_in_weights: p.scale_in_weights,
            headmajor_handoff: p.headmajor_handoff,
            sym_id_base,
            layout,
        }),
    )
    .ok_or_else(|| Error {
        message: format!(
            "{name}: AttnDecode geometry ({geom}) has no const-generic instantiation. The head counts and \
             the head dim parameterise the device layout (GQA grouping, slabs, head strides), so \
             they must be consts, not values. The instantiations are read from the model configs in \
             scope ({}); this geometry belongs to none of them.",
            scratchy_subtile::model_geometry::geometry_sources(),
        ),
    })?
}

/// The orphan-rule carrier for [`lk::RopeAt`] — see the module header.
struct RopeAt<'a>(lk::RopeAt<'a>);

impl scratchy_subtile::model_geometry::OnHeadDim for RopeAt<'_> {
    type Out = Result<Vec<EmittedOp>, Error>;
    fn on_head_dim<const HD: u32>(self) -> Self::Out {
        rope_at::<HD>(self.0)
    }
}

/// ⭐ THE DOOR. main's `lower_rope_node` read `mq`/`total` off a `TileOp` built from the node and its
/// operand names off `ds_name`. `total` is the node's declared output width and `mq` its row count —
/// both carried on [`KtirNode::out_shape`], because the program states only their product with
/// `heads` (see that field). The head dim is the `x` view's own column extent, and it becomes the
/// const generic through the SAME door main crossed.
fn rope(
    name: &str,
    r: &[Region],
    sym_id_base: &mut i64,
    layout: Option<&BundleLayout>,
    attn_params: Option<BundleAttnParams>,
) -> Result<Vec<EmittedOp>, Error> {
    let (ins, out) = split_out(name, r, layout, 3)?;
    // ⛔ THE WHOLE-TENSOR ROW WINDOW, THE 2a LAW — for BOTH forms below. `rope.py`'s per-row form states a
    // row window (`R_START` baked into every access tile's corner) — the producer's per-position
    // decomposition mints one rope node per tail row, and the splice compiles each one. But
    // `RopeAt` addresses the buffers at their BASES, so a window whose corner is not the
    // tensor's first row would lower to ops that read and write every position shifted by
    // the corner — a silently wrong answer, not a loud one. Refusing here names the gap at
    // the door itself; the row-base extension (an `R_START`-scaled base per buffer) is the
    // 2b worklist item. A whole-region rope states `R_START = 0` and passes untouched.
    for (x, role) in [(&ins[0], "the `x` view"), (&out, "the `out` view")] {
        if x.r_cover != (0, x.v_rows) {
            return err(format!(
                "{name}: {role} covers rows [{}, {}) of {} — a per-row rope window. `RopeAt` \
                 addresses the buffer base, so lowering a windowed rope would shift every \
                 position by the window's corner. The row-base extension is the 2b worklist \
                 item; until it lands, only whole-tensor ropes lower through this door",
                x.r_cover.0, x.r_cover.1, x.v_rows,
            ));
        }
    }
    // ⭐ TWO FORMS, TOLD APART BY THE VIEW'S WIDTH, and the access tile is a half-head either way.
    // A rope whose positions outnumber its heads loops over the HEADS (`rope.py`'s `_rope_per_head`):
    // it views `x` as the plane it is, `[mq, heads·hd]`, one `[mq, hd/2]` tile per head half, so its
    // program stops growing with the chunk. Every other rope loops over the POSITIONS and views `x`
    // tall, `[rows·heads, hd]` — the arm below. A tall view is one head dim wide, i.e. exactly twice
    // its tile; a plane view of two or more heads is wider than that.
    if ins[0].c_len > 0 && ins[0].v_cols > 2 * ins[0].c_len {
        let hd = 2 * ins[0].c_len;
        if !ins[0].v_cols.is_multiple_of(hd) || ins[0].r_len != ins[0].v_rows {
            return err(format!(
                "{name}: the `x` view states `[{}, {}]` and its first tile `[{}, {}]` — a per-head \
                 rope tiles every row of a plane a whole number of heads wide, half a head at a time",
                ins[0].v_rows, ins[0].v_cols, ins[0].r_len, ins[0].c_len,
            ));
        }
        return rope_at_geometry(
            name,
            &ins,
            &out,
            RopePlane {
                hd,
                mq: ins[0].v_rows,
                total: ins[0].v_cols,
            },
            sym_id_base,
            layout,
            attn_params,
        );
    }
    // The rope program views `x` as `[rows·heads, hd]`, so the view's COLUMN extent is the head dim.
    let hd = ins[0].v_cols;
    // ⭐⭐⭐ ROWS AND WIDTH, BOTH READ OFF THE PROGRAM — AND THE READING IS THE TILE, NOT A VIEW.
    // The rope program views `x` as `[rows·heads, hd]` and takes one access tile
    // `(ri·heads, 0, heads, half)` per position, so the ACCESS TILE's row extent IS `heads` — the
    // fact the two
    // view extents multiply together and neither states alone. `regions()` already records it as
    // `Region::r_len`. With `heads` known the view's own row count divides into the positions, and the
    // node's real width is `heads · hd`.
    //
    // ⛔ NOT THE COS VIEW. It looked like the answer — cos is one row per position — but `rope` binds
    // it through `load_1d(cos_t, rows·tbl_cols, ri·tbl_cols, half)`, i.e. ONE-DIMENSIONAL, so its view
    // is `(1, rows·tbl_cols)` and its row extent is 1 for every model. Reading it as the position
    // count made granite-3.1-8b's `[2, 4096]` rope output into `[1, 8192]`, which the arrangement
    // authority caught as a same-tensor layout conflict on t729. The half-width is `c_len` here, so
    // `hd == 2 · c_len` is checked below rather than assumed.
    let heads = ins[0].r_len;
    if heads == 0 || hd == 0 {
        return err(format!(
            "{name}: the `x` view states `[{}, {hd}]` and its access tile {heads} row(s) — a rope \
             needs a nonzero head dim and at least one head",
            ins[0].v_rows,
        ));
    }
    if ins[0].v_rows % heads != 0 {
        return err(format!(
            "{name}: the `x` view states {} row(s) over an access tile of {heads} head(s), which does \
             not divide — the rope program views `x` as `rows·heads` by `hd`, so the head count must \
             tile its rows exactly",
            ins[0].v_rows,
        ));
    }
    if ins[0].c_len * 2 != hd {
        return err(format!(
            "{name}: the `x` access tile takes {} column(s) of a {hd}-wide view — a rope rotates \
             half-width slices, so the window must be exactly `hd / 2`",
            ins[0].c_len,
        ));
    }
    let mq = ins[0].v_rows / heads;
    let total = heads * hd;
    rope_at_geometry(
        name,
        &ins,
        &out,
        RopePlane { hd, mq, total },
        sym_id_base,
        layout,
        attn_params,
    )
}

/// What a rope program states about its plane, whichever form stated it: the head dim, and the
/// `[mq, total]` plane's rows and width. Both forms describe the same bytes, so the device program is
/// one function of these three numbers.
#[derive(Clone, Copy)]
struct RopePlane {
    hd: u32,
    mq: u32,
    total: u32,
}

/// The rope's lowering once its [`RopePlane`] is read.
fn rope_at_geometry(
    name: &str,
    ins: &[Region],
    out: &Region,
    plane: RopePlane,
    sym_id_base: &mut i64,
    layout: Option<&BundleLayout>,
    attn_params: Option<BundleAttnParams>,
) -> Result<Vec<EmittedOp>, Error> {
    let RopePlane { hd, mq, total } = plane;
    // ⛔ THE ROW KIND, AS A PARAMETER — main's `LowerRope::rows_are_requests`, which main also took as
    // a parameter and for the reason its own comment gives. It decides whether the head-major collapse
    // may span the query rows, which is a DEVICE law: the rope program never receives the fact and
    // emits the same ops either way, so no program can state it. A rope in a bundle with no attention
    // node has no requests to have rows of, which is main's own `false` at that call site.
    let rows_are_requests = attn_params.is_some_and(|p| p.rows_are_requests);
    // ⭐⭐ THE ONE PLACE THE HEAD DIM STOPS BEING A VALUE, the same door `lower_one_node` crossed for
    // the SubtileIR path: the arms are every head dim the workspace's model configs declare, and a
    // head dim with no arm is a loud bake error answered by a `config.json`.
    if hd == 0 {
        return err(format!("{name}: the `x` view states a zero head dim"));
    }
    // ⭐ THE ROPE-P CLASS TID — which `[hd,hd]` P table this rope's `matmul(x, P)` names. The class
    // set is the bake's OWN registry (`BundleLayout::rope_class_hds`, the same registry mechanism
    // `scalarmul_scales` established), so the emitter, the placement pass and the worker's load-time
    // bind all resolve class↔tid through ONE list. A rope arriving with no registry, or a head dim
    // the registry does not hold, is a desync — refuse it rather than guessing class 0.
    let p_tid = layout
        .and_then(|l| l.rope_class_hds.iter().position(|&h| h == hd))
        .map(ktir_superdsc::reserved_tids::rope_p_class_tid)
        .ok_or_else(|| Error {
            message: format!(
                "{name}: rope head_dim {hd} absent from BundleLayout.rope_class_hds {:?} (registry \
                 desync — the placement pass and this lowering disagree about the tape's rope \
                 classes, so which P table this rope reads is not a fact either of them states)",
                layout.map(|l| l.rope_class_hds.clone()).unwrap_or_default(),
            ),
        })?;
    scratchy_subtile::model_geometry::with_config_head_dim(
        scratchy_subtile::model_geometry::HeadDim::new(hd),
        RopeAt(lk::RopeAt {
            name,
            x: ins[0].name(),
            cos: ins[1].name(),
            sin: ins[2].name(),
            out: out.name(),
            t: out.tid,
            mq,
            total,
            p_tid,
            sym_id_base,
            layout,
            rows_are_requests,
        }),
    )
    .ok_or_else(|| Error {
        message: format!(
            "{name}: head_dim {hd} has no const-generic instantiation. The head dim parameterises \
             the device layout (slabs = head_dim/lanes, and the head-major collapse is valid only at \
             head_dim == lanes), so it must be a const, not a value. The instantiations are read \
             from the model configs in scope ({}); this head dim belongs to none of them.",
            scratchy_subtile::model_geometry::geometry_sources(),
        ),
    })?
}
